script:
"=== RustDesk status ==="
Get-Process rustdesk -ErrorAction SilentlyContinue | Select-Object Id, ProcessName | Select-Object -First 3
"=== ID file ==="
$idPaths = @(
  "$env:APPDATA\RustDesk\config\id.txt",
  "$env:USERPROFILE\.config\RustDesk\id.txt"
)
foreach ($p in $idPaths) {
  if (Test-Path $p) { "ID at $p : " + (Get-Content $p).Trim() }
}
"=== trying to get ID via CLI ==="
$exe = "${env:ProgramFiles}\RustDesk\RustDesk.exe"
if (Test-Path $exe) {
  try { & $exe --get-id 2>&1 | Select-Object -First 3 } catch { "CLI failed" }
}
